<?php use yii\helpers\Html; use yii\helpers\Url; $this->title='Rekrutmen'; $statusLabels=['open'=>'Pendaftaran Dibuka','closed'=>'Pendaftaran Ditutup','announced'=>'Pengumuman Terbit']; ?>
<section class="page-hero"><div class="container"><span class="section-kicker">REKRUTMEN</span><h1>Temukan batch pengabdianmu.</h1><p>Satu portal untuk pendaftaran, verifikasi, seleksi, wawancara, hingga pengumuman.</p></div></section><section class="section"><div class="container batch-list"><?php if(!$batches): ?><div class="empty-card"><h3>Belum ada batch yang dipublikasikan.</h3><p>Informasi rekrutmen berikutnya akan tampil di halaman ini.</p></div><?php endif; ?><?php foreach($batches as $batch): ?><article class="batch-card"><div><span class="batch-status <?= Html::encode($batch->status) ?>"><?= Html::encode($statusLabels[$batch->status] ?? 'Informasi Rekrutmen') ?></span><h2><?= Html::encode($batch->title) ?></h2><p><?= Html::encode($batch->description ?: 'Program pengabdian Sumut Mengajar.') ?></p></div><div class="batch-card-foot"><span>Batch <?= (int)$batch->batch_number ?></span><a href="<?= Url::to(['/recruitment/view','slug'=>$batch->slug]) ?>">Detail →</a></div></article><?php endforeach; ?></div></section>
